const labrastroPruneSkillPackageFolders = `-- name: LabrastroPruneSkillPackageFolders :exec
WITH RECURSIVE occupied AS (
    SELECT f.id,f.parent_id FROM labrastro_skill_folder f
    WHERE f.workspace_id=$1 AND EXISTS (
        SELECT 1 FROM labrastro_skill_placement p
        WHERE p.workspace_id=f.workspace_id AND p.folder_id=f.id
    )
    UNION
    SELECT f.id,f.parent_id FROM labrastro_skill_folder f
    JOIN occupied o ON o.parent_id=f.id
    WHERE f.workspace_id=$1
)
DELETE FROM labrastro_skill_folder f
WHERE f.workspace_id=$1 AND f.package_id=$2
AND (NOT $3::boolean OR f.package_path <> '')
AND NOT EXISTS (SELECT 1 FROM occupied o WHERE o.id=f.id)
`

type LabrastroPruneSkillPackageFoldersParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	PackageID   pgtype.UUID `json:"package_id"`
	KeepRoot    bool        `json:"keep_root"`
}

func (q *Queries) LabrastroPruneSkillPackageFolders(ctx context.Context, arg LabrastroPruneSkillPackageFoldersParams) error {
	_, err := q.db.Exec(ctx, labrastroPruneSkillPackageFolders, arg.WorkspaceID, arg.PackageID, arg.KeepRoot)
	return err
}

