const labrastroSkillBindingImpact = `-- name: LabrastroSkillBindingImpact :many
SELECT a.id,a.name,s.id AS skill_id,s.name AS skill_name FROM agent_skill b
JOIN agent a ON a.id=b.agent_id JOIN skill s ON s.id=b.skill_id AND s.workspace_id=a.workspace_id
WHERE s.workspace_id=$1 AND s.id=ANY($2::uuid[]) ORDER BY a.id,s.id
`

type LabrastroSkillBindingImpactParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	SkillIds    []pgtype.UUID `json:"skill_ids"`
}

type LabrastroSkillBindingImpactRow struct {
	ID        pgtype.UUID `json:"id"`
	Name      string      `json:"name"`
	SkillID   pgtype.UUID `json:"skill_id"`
	SkillName string      `json:"skill_name"`
}

func (q *Queries) LabrastroSkillBindingImpact(ctx context.Context, arg LabrastroSkillBindingImpactParams) ([]LabrastroSkillBindingImpactRow, error) {
	rows, err := q.db.Query(ctx, labrastroSkillBindingImpact, arg.WorkspaceID, arg.SkillIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LabrastroSkillBindingImpactRow{}
	for rows.Next() {
		var i LabrastroSkillBindingImpactRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.SkillID,
			&i.SkillName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

